                zjisti_sloupce(gf, vlastnosti) {
                    var ss = "";
                    if (vlastnosti == true)
                        ss = gf.columns.filter(e => e.hidden != true).filter(f => f.name.includes('ControlsSystemAggregated') != true).map(e => e.name).join(',');
                    else
                        ss = gf.columns.filter(e => e.hidden != true).filter(f => f.name.includes('ControlsSystemAggregated') != true).filter(f => f.name.includes('Vlastnost') != true).map(e => e.name).join(',');
                    //console.log('', ss);
                    return ss; // gf.columns.filter(e => e.hidden != true).map(e => e.name).join(',');
                    //return "stav_inp,zpracovatel,aktivita,ixs_pla_txt,cislo,nazev,nks,t_nks,c_2,c_2_3_7_8,c_23_25,c_2_3_7_8_23_25,c_6_18,rezervovano_proc,c_0,cerpano_proc,ixs_fun_akt_nazev,adresa1,adresa2,psc,adresa3"
                }
                zjisti_sloupce_search(gf) {
                    return gf.columns.filter(e => e.hidden != true).filter(e => e.columnType == "text").map(e => { return '*' + e.name; });
                }
                showComparison(rows) {
                    var that = this;
                    if (rows.length > 0) {
                        var dataRows = rows.map(function (item, idx) { return item.data; }); // převod z grid metadata-view do pole dto
                        if (this.isComparisonInited) {
                            this.addToComparison(dataRows);
                        }
                        else {
                            this.isComparisonInited = true;
                            this.comparisonCnt.empty();
                            this.comparator = $('<div class="js-detail-comparator">').appendTo(this.comparisonCnt).gcomparator({
                                items: dataRows,
                                columns: that.mainTable.ggrid("option", "columns"),
                                itemTemplate: "{cislo}",
                                itemchange: function (ev, ctx) {
                                    that.comparisonBadge.value = ctx.count.toString();
                                    that.comparisonBadge.update();
                                },
                                selection: function (ev, ctx) {
                                    that.mainTable.ggrid("activeRow", ctx.item);
                                }
                            });
                        }
                        for (var row in rows) {
                            rows[row].checked = false;
                        }
                        this.mainTable.ggrid("refresh");
                    }
                }
                addToComparison(rows) {
                    this.comparator.gcomparator("addItems", rows);
                }
